from collections import deque
G=grid; R=len(G); C=len(G[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if G[r][c] and (r,c) not in seen:
   col=G[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop(); comp.append((x,y,col))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     z=(x+dx,y+dy)
     if 0<=z[0]<R and 0<=z[1]<C and z not in seen and G[z[0]][z[1]]==col: seen.add(z);q.append(z)
   comps.append(comp)
# rightmost-first, slide max while no other occupied
comps.sort(key=lambda a:max(y for x,y,v in a),reverse=True)
out=[[0]*C for _ in range(R)]
for comp in comps:
 d=0
 while all(y+d+1<C and out[x][y+d+1]==0 for x,y,v in comp): d+=1
 for x,y,v in comp: out[x][y+d]=v
